// ============================================================
// UnalignAdd kernel: 双输入逐元素加法
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelUnalignAdd {
public:
    __aicore__ inline KernelUnalignAdd() {}

    __aicore__ inline void Init(GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        int64_t offset = 0;

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            offset = formerLength * blockIdx;
            input1Gm.SetGlobalBuffer((__gm__ T *)input1 + offset, formerLength);
            input2Gm.SetGlobalBuffer((__gm__ T *)input2 + offset, formerLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            offset = formerLength * formerNum + tailLength * tailIdx;
            input1Gm.SetGlobalBuffer((__gm__ T *)input1 + offset, tailLength);
            input2Gm.SetGlobalBuffer((__gm__ T *)input2 + offset, tailLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) < sizeof(float)) {
            pipe.InitBuffer(tempBufX, tileLength * sizeof(float));
            pipe.InitBuffer(tempBufY, tileLength * sizeof(float));
            pipe.InitBuffer(tempBufZ, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams xCopyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)),
                                               0, 0, 0};
        AscendC::DataCopyPad(xLocal, input1Gm[progress * this->tileLength], xCopyParams);
        inQueueX.EnQue(xLocal);

        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();
        AscendC::DataCopyExtParams yCopyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)),
                                               0, 0, 0};
        AscendC::DataCopyPad(yLocal, input2Gm[progress * this->tileLength], yCopyParams);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        if constexpr (sizeof(T) == sizeof(float)) {
            // fp32: 直接计算
            AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
            AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
            AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();

            AscendC::Add(zLocal, xLocal, yLocal, curTileLength);

            outQueueZ.EnQue<T>(zLocal);
            inQueueX.FreeTensor(xLocal);
            inQueueY.FreeTensor(yLocal);
        } else {
            // fp16/bf16: 升精度到 fp32 计算
            AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
            AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
            AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();

            AscendC::LocalTensor<float> xFp32 = tempBufX.Get<float>();
            AscendC::LocalTensor<float> yFp32 = tempBufY.Get<float>();
            AscendC::LocalTensor<float> zFp32 = tempBufZ.Get<float>();

            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Add(zFp32, xFp32, yFp32, curTileLength);
            AscendC::Cast(zLocal, zFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);

            outQueueZ.EnQue<T>(zLocal);
            inQueueX.FreeTensor(xLocal);
            inQueueY.FreeTensor(yLocal);
        }
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> zLocal = outQueueZ.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)),
                                              0, 0, 0};
        AscendC::DataCopyPad(outputGm[progress * this->tileLength], zLocal, copyParams);
        outQueueZ.FreeTensor(zLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufZ;
    AscendC::GlobalTensor<T> input1Gm;
    AscendC::GlobalTensor<T> input2Gm;
    AscendC::GlobalTensor<T> outputGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void unalign_add(GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
                                                    int64_t formerNum, int64_t formerLength,
                                                    int64_t tailLength, int64_t tileLength,
                                                    int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelUnalignAdd<half> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelUnalignAdd<float> op;
        op.Init(input1, input2, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
