// ============================================================
// UnalignAdd host 端: tiling 计算 + kernel 启动
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_unalign_add.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t SYSTEM_WORKSPACE_SIZE = 16 * 1024 * 1024;  // 16MB

at::Tensor unalign_add(const at::Tensor &input1, const at::Tensor &input2)
{
    // ---- 输入校验 ----
    TORCH_CHECK(input1.scalar_type() == at::kHalf || input1.scalar_type() == at::kFloat ||
                input1.scalar_type() == at::kBFloat16,
                "unalign_add: only float16, float32 and bfloat16 are supported, got ",
                input1.scalar_type());
    TORCH_CHECK(input1.scalar_type() == input2.scalar_type(),
                "unalign_add: input1 and input2 must have the same dtype");
    TORCH_CHECK(input1.sizes() == input2.sizes(),
                "unalign_add: input1 and input2 must have the same shape");

    at::Tensor output = at::empty_like(input1);

    int64_t totalLength = input1.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = input1.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    // bufferCoefficient: fp32=32, fp16/bf16=24 (来自 UB 分配表)
    int64_t bufferCoefficient = (dtypeSize == 4) ? 32 : 24;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    // ---- workspace 分配 ----
    int64_t workspaceSizeVal = SYSTEM_WORKSPACE_SIZE;
    auto workspace = at::empty({workspaceSizeVal},
                               at::TensorOptions().dtype(at::kByte).device(input1.device()));

    // ---- Kernel 启动 (所有参数均为左值) ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(unalign_add, blockDim,
                    input1, input2, output,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize);

    return output;
}

}  // namespace ascend_kernel
