19	constexpr int32_t BUFFER_NUM = 2;
20	
21	template <typename T>
22	class KernelUnalignAdd {
23	public:
24	    __aicore__ inline KernelUnalignAdd() {}
25	
26	    __aicore__ inline void Init(GM_ADDR input1, GM_ADDR input2, GM_ADDR output,
27	                                int64_t formerNum, int64_t formerLength,
28	                                int64_t tailLength, int64_t tileLength)
29	    {
30	        int64_t blockIdx = AscendC::GetBlockIdx();
31	        int64_t offset = 0;
32	
33	        if (blockIdx < formerNum) {
34	            this->blockLength = formerLength;
35	            offset = formerLength * blockIdx;
36	            input1Gm.SetGlobalBuffer((__gm__ T *)input1 + offset, formerLength);
37	            input2Gm.SetGlobalBuffer((__gm__ T *)input2 + offset, formerLength);
38	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
39	        } else {
40	            this->blockLength = tailLength;
41	            int64_t tailIdx = blockIdx - formerNum;
42	            offset = formerLength * formerNum + tailLength * tailIdx;
43	            input1Gm.SetGlobalBuffer((__gm__ T *)input1 + offset, tailLength);
44	            input2Gm.SetGlobalBuffer((__gm__ T *)input2 + offset, tailLength);
45	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
46	        }
47	
48	        this->tileLength = tileLength;
49	
50	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
51	        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
52	        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(T));
53	
54	        if constexpr (sizeof(T) < sizeof(float)) {
55	            pipe.InitBuffer(tempBufX, tileLength * sizeof(float));
56	            pipe.InitBuffer(tempBufY, tileLength * sizeof(float));
57	            pipe.InitBuffer(tempBufZ, tileLength * sizeof(float));
58	        }
59	    }
60	
61	    __aicore__ inline void Process()
62	    {
63	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
64	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
65	
66	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
67	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
68	
69	        for (int64_t i = 0; i < tileNum - 1; ++i) {
70	            CopyIn(i, this->tileLength);
71	            Compute(i, this->tileLength);
72	            CopyOut(i, this->tileLength);
73	        }
74	        if (tileNum > 0) {
75	            CopyIn(tileNum - 1, alignedTailLen);
76	            Compute(tileNum - 1, alignedTailLen);
77	            CopyOut(tileNum - 1, alignedTailLen);
78	        }
79	    }
