81	private:
82	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
83	    {
84	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
85	        AscendC::DataCopyExtParams xCopyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)),
86	                                               0, 0, 0};
87	        AscendC::DataCopyPad(xLocal, input1Gm[progress * this->tileLength], xCopyParams);
88	        inQueueX.EnQue(xLocal);
89	
90	        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();
91	        AscendC::DataCopyExtParams yCopyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)),
92	                                               0, 0, 0};
93	        AscendC::DataCopyPad(yLocal, input2Gm[progress * this->tileLength], yCopyParams);
94	        inQueueY.EnQue(yLocal);
95	    }
96	
97	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
98	    {
99	        if constexpr (sizeof(T) == sizeof(float)) {
100	            // fp32: 直接计算
101	            AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
102	            AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
103	            AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();
104	
105	            AscendC::Add(zLocal, xLocal, yLocal, curTileLength);
106	
107	            outQueueZ.EnQue<T>(zLocal);
108	            inQueueX.FreeTensor(xLocal);
109	            inQueueY.FreeTensor(yLocal);
110	        } else {
111	            // fp16/bf16: 升精度到 fp32 计算
112	            AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
113	            AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
114	            AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();
115	
116	            AscendC::LocalTensor<float> xFp32 = tempBufX.Get<float>();
117	            AscendC::LocalTensor<float> yFp32 = tempBufY.Get<float>();
118	            AscendC::LocalTensor<float> zFp32 = tempBufZ.Get<float>();
119	
120	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
121	            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
122	            AscendC::Add(zFp32, xFp32, yFp32, curTileLength);
123	            AscendC::Cast(zLocal, zFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
124	
125	            outQueueZ.EnQue<T>(zLocal);
126	            inQueueX.FreeTensor(xLocal);
127	            inQueueY.FreeTensor(yLocal);
128	        }
129	    }
130	
131	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
132	    {
133	        AscendC::LocalTensor<T> zLocal = outQueueZ.DeQue<T>();
134	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)),
135	                                              0, 0, 0};
136	        AscendC::DataCopyPad(outputGm[progress * this->tileLength], zLocal, copyParams);
137	        outQueueZ.FreeTensor(zLocal);
138	    }
139	
140	private:
141	    AscendC::TPipe pipe;
142	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
143	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
144	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
145	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufX;
146	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufY;
147	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufZ;
148	    AscendC::GlobalTensor<T> input1Gm;
149	    AscendC::GlobalTensor<T> input2Gm;
150	    AscendC::GlobalTensor<T> outputGm;
151	    int64_t blockLength;
152	    int64_t tileLength;
153	};
